    if (messages.length === 0) {
      console.warn('[选项美化] 未找到当前消息');
      options.value = [];
      emptyReason.value = 'no-message';
      return;
    }

    const message = messages[0];
    const messageText = message.message;

    // 使用正则表达式提取 <option> 标签中的内容
    const regex = /<option>([\s\S]*?)<\/option>/;
